# -*- coding: utf-8 -*-
"""Колір ОБРАЗУ: набір реальних речей (hex із каталогу) + особа (colorspace.features)
-> перелік знахідок, кожна з РЕМОНТОМ і, де можливо, ЗАПИТОМ У КАТАЛОГ.

Що цей файл змінює в рішенні (before/after):
  без нього    — композитор бере речі, що «пасують за тегами», і віддає образ;
  з ним        — образ або проходить, або повертається з конкретним слотом на заміну
                 і числовим вікном (L*, C*, сім'я), яким можна ФІЛЬТРУВАТИ каталог.
Тобто вихід — не оцінка, а наступний запит на реальну річ.

Межі: тут лише колір. Посадка, формальність, погода, силует — інші модулі.
Усі пороги — фольклорні константи (T3), не калібровані на golden set. Тому кожна
знахідка несе поріг, за яким її ухвалено, і падає до «hint», якщо вимір лежить
у смузі невизначеності біля порога (сила ≤ верифікація)."""
import re
import math
import statistics
import ід_правил as ІП
import colorspace as cs
from colorspace import hx, lch, c_max, de00, reliability, MIN_TO_EMIT, регіони, _розсіяння

